import AsyncStorage from "@react-native-async-storage/async-storage";
import MaterialIcons from "@expo/vector-icons/MaterialIcons";
import React, { useEffect, useMemo, useState } from "react";
import {
  Alert,
  FlatList,
  Modal,
  Pressable,
  ScrollView,
  StyleSheet,
  Switch,
  Text,
  TextInput,
  View,
} from "react-native";
import { ScreenContainer } from "@/components/screen-container";

type Client = { id: string; name: string; document: string; phone: string; route: string; status: string; note?: string };
type Loan = { id: string; clientId: string; capital: number; interest: number; installments: number; installment: number; frequency: string; start: string; due: string; status: string; paid: number; lateFee: number; grace: number; note?: string };
type Payment = { id: string; loanId: string; clientId: string; amount: number; date: string; kind: string; receipt: string };
type Expense = { id: string; title: string; amount: number; date: string; category: string };
type Route = { id: string; name: string; clients: string[] };
type AppState = { clients: Client[]; loans: Loan[]; payments: Payment[]; expenses: Expense[]; routes: Route[]; business: { name: string; currency: string; signature: string }; dark: boolean };

type Screen = { name: string; id?: string; tab?: string };
const today = new Date().toLocaleDateString("pt-BR");
const seed: AppState = {
  clients: [
    { id: "c1", name: "Maria Oliveira", document: "CPF 123.456.789-00", phone: "(11) 98888-2211", route: "Rota Centro", status: "Em formação", note: "Prefere contato pela manhã." },
    { id: "c2", name: "João Santos", document: "CPF 987.654.321-00", phone: "(11) 97777-1020", route: "Rota Norte", status: "Ativo" },
    { id: "c3", name: "Ana Souza", document: "CPF 111.222.333-44", phone: "(11) 96666-3040", route: "Não alocado", status: "Ativo" },
  ],
  loans: [
    { id: "L-1048", clientId: "c1", capital: 2400, interest: 20, installments: 12, installment: 240, frequency: "Semanal", start: "01/09/2026", due: "24/11/2026", status: "Ativo", paid: 720, lateFee: 2, grace: 2, note: "Crédito para capital de giro." },
    { id: "L-1049", clientId: "c2", capital: 1200, interest: 15, installments: 8, installment: 172.5, frequency: "Quinzenal", start: "15/08/2026", due: "15/12/2026", status: "Atrasado", paid: 345, lateFee: 3, grace: 1 },
  ],
  payments: [{ id: "P-2001", loanId: "L-1048", clientId: "c1", amount: 240, date: today, kind: "Exato", receipt: "REC-0001" }],
  expenses: [{ id: "E-01", title: "Combustível", amount: 90, date: today, category: "Operacional" }],
  routes: [{ id: "r1", name: "Rota Centro", clients: ["c1"] }, { id: "r2", name: "Rota Norte", clients: ["c2"] }],
  business: { name: "Roots Cobrança", currency: "BRL", signature: "Equipe Roots" }, dark: true,
};

const money = (n: number) => `R$ ${n.toFixed(2).replace(".", ",")}`;
const uid = (prefix: string) => `${prefix}-${Math.floor(Math.random() * 9000 + 1000)}`;

export default function HomeScreen() {
  const [state, setState] = useState<AppState>(seed);
  const [screen, setScreen] = useState<Screen>({ name: "dashboard" });
  const [search, setSearch] = useState("");
  const [modal, setModal] = useState<"actions" | "date" | "more" | null>(null);
  const [toast, setToast] = useState("");

  useEffect(() => { AsyncStorage.getItem("roots-state").then((raw) => raw && setState(JSON.parse(raw))); }, []);
  useEffect(() => { AsyncStorage.setItem("roots-state", JSON.stringify(state)); }, [state]);
  const notify = (message: string) => { setToast(message); setTimeout(() => setToast(""), 2200); };
  const go = (name: string, id?: string, tab?: string) => { setModal(null); setScreen({ name, id, tab }); setSearch(""); };
  const client = state.clients.find((c) => c.id === screen.id);
  const loan = state.loans.find((l) => l.id === screen.id);

  const addClient = (data: Partial<Client>) => { const next = { id: uid("c"), name: data.name || "Novo cliente", document: data.document || "Não informado", phone: data.phone || "Não informado", route: data.route || "Não alocado", status: "Em formação", note: data.note }; setState((s) => ({ ...s, clients: [...s.clients, next] })); notify("Cliente criado"); go("client", next.id); };
  const addLoan = (data: Partial<Loan>) => { const capital = Number(data.capital || 0); const interest = Number(data.interest || 0); const installments = Number(data.installments || 1); const total = capital * (1 + interest / 100); const next: Loan = { id: uid("L"), clientId: data.clientId || state.clients[0]?.id || "", capital, interest, installments, installment: Number(data.installment || total / installments), frequency: data.frequency || "Semanal", start: data.start || today, due: data.due || today, status: "Ativo", paid: 0, lateFee: Number(data.lateFee || 0), grace: Number(data.grace || 0), note: data.note }; setState((s) => ({ ...s, loans: [...s.loans, next] })); notify("Crédito criado"); go("loan", next.id); };
  const registerPayment = (amount: number, kind: string) => { if (!loan || !amount) return; const payment: Payment = { id: uid("P"), loanId: loan.id, clientId: loan.clientId, amount, date: today, kind, receipt: uid("REC") }; setState((s) => ({ ...s, payments: [payment, ...s.payments], loans: s.loans.map((l) => l.id === loan.id ? { ...l, paid: l.paid + amount, status: l.paid + amount >= l.capital * (1 + l.interest / 100) ? "Pago" : l.status } : l) })); notify("Pagamento registrado no Caixa"); go("receipt", payment.id); };
  const removeClient = () => { if (!client) return; Alert.alert("Remover cliente", "Essa ação remove o cliente da carteira.", [{ text: "Cancelar" }, { text: "Remover", style: "destructive", onPress: () => { setState((s) => ({ ...s, clients: s.clients.filter((c) => c.id !== client.id), loans: s.loans.filter((l) => l.clientId !== client.id) })); go("clients"); notify("Cliente removido"); } }]); };
  const filteredClients = state.clients.filter((c) => `${c.name} ${c.document}`.toLowerCase().includes(search.toLowerCase()));

  return <ScreenContainer containerClassName="bg-[#0e0f14]" safeAreaClassName="bg-[#0e0f14]">
    <View style={styles.app}>
      {screen.name === "dashboard" && <Dashboard state={state} go={go} setModal={setModal} notify={notify} />}
      {screen.name === "clients" && <Clients clients={filteredClients} search={search} setSearch={setSearch} go={go} />}
      {screen.name === "client" && client && <ClientDetail client={client} state={state} go={go} remove={removeClient} />}
      {screen.name === "client-form" && <ClientForm add={addClient} go={go} />}
      {screen.name === "loans" && <Loans state={state} go={go} />}
      {screen.name === "loan" && loan && <LoanDetail loan={loan} state={state} go={go} registerPayment={registerPayment} notify={notify} />}
      {screen.name === "loan-form" && <LoanForm state={state} add={addLoan} go={go} />}
      {screen.name === "loan-info" && loan && <LoanInfo loan={loan} state={state} go={go} />}
      {screen.name === "payment" && loan && <PaymentForm loan={loan} register={registerPayment} go={go} />}
      {screen.name === "receipt" && <Receipt payment={state.payments.find((p) => p.id === screen.id) || state.payments[0]} state={state} go={go} />}
      {screen.name === "finance" && <Finance state={state} go={go} notify={notify} />}
      {screen.name === "routes" && <Routes state={state} setState={setState} go={go} notify={notify} />}
      {screen.name === "reports" && <Reports state={state} go={go} notify={notify} />}
      {screen.name === "portfolio" && <Portfolio state={state} go={go} />}
      {screen.name === "calculator" && <Calculator go={go} />}
      {screen.name === "settings" && <Settings state={state} setState={setState} go={go} notify={notify} />}
      {screen.name === "more" && <More go={go} />}
      {screen.name === "about" && <About go={go} />}
      {screen.name === "collections" && <Collections state={state} go={go} register={registerPayment} />}
      {screen.name === "expenses" && <Expenses state={state} setState={setState} go={go} notify={notify} />}
      {screen.name === "cash-close" && <CashClose state={state} go={go} notify={notify} />}
      {!(["client", "client-form", "loan", "loan-form", "loan-info", "payment", "receipt", "about", "cash-close"].includes(screen.name)) && <BottomNav active={screen.name} go={go} />}
      {modal === "actions" && <QuickActions go={go} close={() => setModal(null)} />}
      {modal === "date" && <DateModal close={() => setModal(null)} notify={notify} />}
      {modal === "more" && <MoreModal close={() => setModal(null)} go={go} />}
      {!!toast && <View style={styles.toast}><Text style={styles.toastText}>{toast}</Text></View>}
    </View>
  </ScreenContainer>;
}

function Header({ title, subtitle, go, right }: { title: string; subtitle?: string; go: (n: string, id?: string, tab?: string) => void; right?: React.ReactNode }) { return <View style={styles.header}><View style={styles.headerTop}><Pressable onPress={() => go("dashboard")} style={styles.brand}><View style={styles.logo}><Text style={styles.logoText}>R</Text></View><View><Text style={styles.eyebrow}>ROOTS</Text><Text style={styles.headerTitle}>{title}</Text></View></Pressable><View style={styles.headerActions}>{right || <><IconButton icon="notifications-none" onPress={() => Alert.alert("Notificações", "Nenhuma notificação nova.")} /><IconButton icon="calendar-today" onPress={() => Alert.alert("Agenda", "Agenda de cobranças atualizada.")} /><IconButton icon="file-download" onPress={() => Alert.alert("Exportação", "Relatório preparado para exportação.")} /></>}</View></View>{subtitle && <Text style={styles.headerSub}>{subtitle}</Text>}</View>; }
function IconButton({ icon, onPress }: { icon: keyof typeof MaterialIcons.glyphMap; onPress: () => void }) { return <Pressable onPress={onPress} style={({ pressed }) => [styles.iconButton, pressed && styles.pressed]}><MaterialIcons name={icon} size={20} color="#a8b0bc" /></Pressable>; }
function Button({ title, onPress, color = "#34d399", outline = false, small = false, icon }: { title: string; onPress: () => void; color?: string; outline?: boolean; small?: boolean; icon?: keyof typeof MaterialIcons.glyphMap }) { return <Pressable onPress={onPress} style={({ pressed }) => [styles.button, small && styles.buttonSmall, outline ? { borderColor: color, backgroundColor: "transparent" } : { backgroundColor: color }, pressed && styles.pressed]}>{icon && <MaterialIcons name={icon} size={16} color={outline ? color : "#081312"} />}<Text style={[styles.buttonText, outline && { color }, small && { fontSize: 12 }]}>{title}</Text></Pressable>; }
function Card({ children, style }: { children: React.ReactNode; style?: object }) { return <View style={[styles.card, style]}>{children}</View>; }
function SectionTitle({ title, action, onPress }: { title: string; action?: string; onPress?: () => void }) { return <View style={styles.sectionTitle}><Text style={styles.sectionText}>{title}</Text>{action && <Pressable onPress={onPress}><Text style={styles.link}>{action}</Text></Pressable>}</View>; }
function Stat({ label, value, color }: { label: string; value: string; color: string }) { return <View style={styles.stat}><View style={[styles.dot, { backgroundColor: color }]} /><Text style={styles.statLabel}>{label}</Text><Text style={styles.statValue}>{value}</Text></View>; }

function Dashboard({ state, go, setModal, notify }: { state: AppState; go: (n: string, id?: string, tab?: string) => void; setModal: (m: any) => void; notify: (s: string) => void }) { const total = state.loans.reduce((a, l) => a + l.capital * (1 + l.interest / 100), 0); const received = state.loans.reduce((a, l) => a + l.paid, 0); const pending = Math.max(total - received, 0); return <ScrollView showsVerticalScrollIndicator={false} contentContainerStyle={styles.scroll}><Header title="Dashboard" subtitle="Acompanhe sua operação em um só lugar" go={go} /><Pressable style={styles.dateFilter} onPress={() => setModal("date")}><MaterialIcons name="date-range" size={18} color="#34d399" /><Text style={styles.dateText}>Hoje, {today}</Text><MaterialIcons name="keyboard-arrow-down" size={19} color="#81909b" /></Pressable><Card style={styles.heroCard}><View style={styles.heroGlow} /><View style={styles.heroRow}><View><Text style={styles.miniLabel}>COBRANÇAS DO DIA</Text><Text style={styles.heroValue}>{money(received)}</Text><Text style={styles.heroMuted}>de {money(total)} previstos</Text></View><View style={styles.progressRing}><Text style={styles.ringValue}>{total ? Math.round(received / total * 100) : 0}%</Text></View></View><View style={styles.progressTrack}><View style={[styles.progressFill, { width: `${total ? Math.min(100, received / total * 100) : 0}%` }]} /></View><View style={styles.heroBottom}><Text style={styles.heroMuted}>Recebido hoje</Text><Text style={styles.heroMuted}>{money(pending)} pendente</Text></View></Card><SectionTitle title="Ações rápidas" action="Ver todas" onPress={() => setModal("actions")} /><View style={styles.quickGrid}><Quick title="Despesa" icon="receipt-long" color="#f97316" onPress={() => go("expenses")} /><Quick title="Cliente" icon="person-add-alt" color="#3b82f6" onPress={() => go("client-form")} /><Quick title="Empréstimo" icon="payments" color="#a855f7" onPress={() => go("loan-form")} /><Quick title="Calculadora" icon="calculate" color="#fbbf24" onPress={() => go("calculator")} /></View><SectionTitle title="Visão geral" action="Detalhes" onPress={() => go("reports")} /><Card><Stat label="Recebido" value={money(received)} color="#34d399" /><Stat label="Pendente" value={money(pending)} color="#fbbf24" /><Stat label="Em atraso" value={money(state.loans.filter((l) => l.status === "Atrasado").reduce((a, l) => a + l.installment, 0))} color="#f97316" /><Stat label="Despesas" value={money(state.expenses.reduce((a, e) => a + e.amount, 0))} color="#a855f7" /></Card><SectionTitle title="Próximas cobranças" action="Ver cobranças" onPress={() => go("collections")} />{state.loans.slice(0, 3).map((l) => { const c = state.clients.find((x) => x.id === l.clientId); return <Pressable key={l.id} onPress={() => go("loan", l.id)}><Card style={styles.collectionRow}><Avatar name={c?.name || "Cliente"} size={42} /><View style={styles.flex}><Text style={styles.rowTitle}>{c?.name}</Text><Text style={styles.rowMeta}>{l.frequency} · vence {l.due}</Text></View><View style={styles.alignRight}><Text style={styles.amount}>{money(l.installment)}</Text><Badge text={l.status} color={l.status === "Atrasado" ? "#f97316" : "#34d399"} /></View></Card></Pressable>; })}<Pressable style={styles.fab} onPress={() => setModal("actions")}><MaterialIcons name="add" size={28} color="#071614" /></Pressable></ScrollView>; }
function Quick({ title, icon, color, onPress }: { title: string; icon: keyof typeof MaterialIcons.glyphMap; color: string; onPress: () => void }) { return <Pressable onPress={onPress} style={({ pressed }) => [styles.quick, pressed && styles.pressed]}><View style={[styles.quickIcon, { backgroundColor: color + "24" }]}><MaterialIcons name={icon} size={21} color={color} /></View><Text style={styles.quickText}>{title}</Text></Pressable>; }
function Avatar({ name, size = 48 }: { name: string; size?: number }) { return <View style={[styles.avatar, { width: size, height: size, borderRadius: size / 2 }]}><Text style={[styles.avatarText, { fontSize: size * .34 }]}>{name.split(" ").map((x) => x[0]).slice(0, 2).join("")}</Text></View>; }
function Badge({ text, color }: { text: string; color: string }) { return <View style={[styles.badge, { backgroundColor: color + "1d" }]}><Text style={[styles.badgeText, { color }]}>{text}</Text></View>; }

function Clients({ clients, search, setSearch, go }: { clients: Client[]; search: string; setSearch: (s: string) => void; go: (n: string, id?: string) => void }) { return <View style={styles.flex}><Header title="Clientes" subtitle={`${clients.length} clientes na carteira`} go={go} right={<IconButton icon="person-add" onPress={() => go("client-form")} />} /><View style={styles.searchBox}><MaterialIcons name="search" size={20} color="#77838f" /><TextInput value={search} onChangeText={setSearch} placeholder="Buscar por nome ou documento" placeholderTextColor="#6f7882" style={styles.searchInput} /></View><FlatList data={clients} keyExtractor={(x) => x.id} contentContainerStyle={styles.list} renderItem={({ item }) => <Pressable onPress={() => go("client", item.id)} style={({ pressed }) => [styles.listItem, pressed && styles.pressed]}><Avatar name={item.name} /><View style={styles.flex}><Text style={styles.rowTitle}>{item.name}</Text><Text style={styles.rowMeta}>{item.document}</Text><Text style={styles.rowMeta}>{item.route}</Text></View><View style={styles.alignRight}><Badge text={item.status} color={item.status === "Ativo" ? "#34d399" : "#fbbf24"} /><MaterialIcons name="chevron-right" size={22} color="#68727e" /></View></Pressable>} ListEmptyComponent={<Empty title="Nenhum cliente encontrado" action="Criar cliente" onPress={() => go("client-form")} />} /></View>; }
function ClientDetail({ client, state, go, remove }: { client: Client; state: AppState; go: (n: string, id?: string, tab?: string) => void; remove: () => void }) { const loans = state.loans.filter((l) => l.clientId === client.id); return <ScrollView contentContainerStyle={styles.scroll}><Header title="Detalhe do cliente" go={go} right={<IconButton icon="more-vert" onPress={() => Alert.alert("Mais opções", "Escolha uma ação", [{ text: "Desativar", onPress: () => Alert.alert("Cliente desativado") }, { text: "Remover", style: "destructive", onPress: remove }, { text: "Cancelar" }])} />} /><View style={styles.profile}><Avatar name={client.name} size={76} /><Text style={styles.profileName}>{client.name}</Text><Text style={styles.profileMeta}>{client.document} · {client.phone}</Text><View style={styles.tagRow}><Badge text={client.route} color="#3b82f6" /><Badge text={client.status} color="#34d399" /></View></View><View style={styles.actionRow}><Button title="Editar" icon="edit" small color="#2dd4bf" onPress={() => go("client-form", client.id)} /><Button title="Adicionar crédito" icon="add" small onPress={() => go("loan-form", client.id)} /></View><SectionTitle title="Em formação" /><Card><Info label="Telefone" value={client.phone} /><Info label="Documento" value={client.document} /><Info label="Rota" value={client.route} /><Info label="Observações" value={client.note || "Sem observações"} /></Card><SectionTitle title="Empréstimos Ativos" /><LoanList loans={loans.filter((l) => l.status !== "Pago")} state={state} go={go} empty="Nenhum crédito ativo" /><SectionTitle title="Empréstimos Pagos" /><LoanList loans={loans.filter((l) => l.status === "Pago")} state={state} go={go} empty="Nenhum crédito pago" /></ScrollView>; }
function LoanList({ loans, state, go, empty }: { loans: Loan[]; state: AppState; go: (n: string, id?: string) => void; empty: string }) { if (!loans.length) return <Card><Text style={styles.muted}>{empty}</Text></Card>; return <>{loans.map((l) => <Pressable key={l.id} onPress={() => go("loan", l.id)}><Card style={styles.loanCard}><View style={styles.between}><Text style={styles.rowTitle}>{l.id}</Text><Badge text={l.status} color={l.status === "Atrasado" ? "#f97316" : l.status === "Pago" ? "#3b82f6" : "#34d399"} /></View><Text style={styles.loanClient}>{state.clients.find((c) => c.id === l.clientId)?.name}</Text><View style={styles.loanNumbers}><Info label="Capital" value={money(l.capital)} /><Info label="Parcela" value={money(l.installment)} /><Info label="Pago" value={money(l.paid)} /></View></Card></Pressable>)}</>; }
function Info({ label, value }: { label: string; value: string }) { return <View style={styles.info}><Text style={styles.infoLabel}>{label}</Text><Text style={styles.infoValue}>{value}</Text></View>; }

function ClientForm({ add, go }: { add: (d: Partial<Client>) => void; go: (n: string, id?: string) => void }) { const [name, setName] = useState(""); const [document, setDocument] = useState(""); const [phone, setPhone] = useState(""); const [route, setRoute] = useState("Não alocado"); const [note, setNote] = useState(""); return <ScrollView contentContainerStyle={styles.scroll}><Header title="Novo cliente" subtitle="Em formação" go={go} /><FormInput label="Nome completo" value={name} onChangeText={setName} placeholder="Ex.: Maria Oliveira" /><FormInput label="Documento / identificação" value={document} onChangeText={setDocument} placeholder="CPF, CNPJ ou outro" /><FormInput label="Telefone" value={phone} onChangeText={setPhone} placeholder="(00) 00000-0000" keyboardType="phone-pad" /><FormInput label="Rota" value={route} onChangeText={setRoute} placeholder="Não alocado" /><FormInput label="Observações" value={note} onChangeText={setNote} placeholder="Notas do cliente" multiline /><Button title="Salvar cliente" icon="check" onPress={() => name.trim() ? add({ name, document, phone, route, note }) : Alert.alert("Informe o nome do cliente")} /><Button title="Cancelar" outline color="#78838e" onPress={() => go("clients")} /></ScrollView>; }
function Loans({ state, go }: { state: AppState; go: (n: string, id?: string) => void }) { const [filter, setFilter] = useState("Todos"); const filtered = filter === "Todos" ? state.loans : state.loans.filter((l) => l.status === filter); return <View style={styles.flex}><Header title="Empréstimos / Créditos" subtitle={`${state.loans.length} créditos cadastrados`} go={go} right={<IconButton icon="add" onPress={() => go("loan-form")} />} /><View style={styles.chips}>{["Todos", "Ativo", "Atrasado", "Pago", "Anulada"].map((x) => <Pressable key={x} onPress={() => setFilter(x)} style={filter === x ? styles.chipSelected : styles.chip}><Text style={filter === x ? styles.chipSelectedText : styles.chipText}>{x}</Text></Pressable>)}</View><FlatList data={filtered} keyExtractor={(x) => x.id} contentContainerStyle={styles.list} renderItem={({ item }) => <Pressable onPress={() => go("loan", item.id)}><Card style={styles.loanCard}><View style={styles.between}><View><Text style={styles.rowTitle}>{item.id}</Text><Text style={styles.loanClient}>{state.clients.find((c) => c.id === item.clientId)?.name}</Text></View><Badge text={item.status} color={item.status === "Atrasado" ? "#f97316" : "#34d399"} /></View><View style={styles.loanNumbers}><Info label="Capital" value={money(item.capital)} /><Info label="Juros" value={`${item.interest}%`} /><Info label="Parcelas" value={`${item.installments}x`} /><Info label="Total pago" value={money(item.paid)} /></View></Card></Pressable>} ListEmptyComponent={<Card><Text style={styles.muted}>Nenhum crédito neste filtro</Text></Card>} /></View>; }
function LoanDetail({ loan, state, go, registerPayment, notify }: { loan: Loan; state: AppState; go: (n: string, id?: string, tab?: string) => void; registerPayment: (a: number, k: string) => void; notify: (s: string) => void }) { const [tab, setTab] = useState("Plano de pagamento"); const client = state.clients.find((c) => c.id === loan.clientId); const total = loan.capital * (1 + loan.interest / 100); return <ScrollView contentContainerStyle={styles.scroll}><Header title={client?.name || "Crédito"} subtitle={`${money(loan.capital)} · ${loan.interest}% · ${loan.frequency}`} go={go} right={<IconButton icon="more-vert" onPress={() => Alert.alert("Ações do crédito", "Escolha uma ação", [{ text: "Editar crédito", onPress: () => go("loan-form", loan.id) }, { text: "Remover crédito", style: "destructive", onPress: () => notify("Crédito preparado para remoção") }, { text: "Cancelar" }])} />} /><Card style={styles.creditHero}><View style={styles.between}><View><Text style={styles.miniLabel}>STATUS DO CRÉDITO</Text><Text style={styles.creditStatus}>{loan.status}</Text></View><Text style={styles.creditCapital}>{money(loan.capital)}</Text></View><View style={styles.creditMeta}><Text style={styles.heroMuted}>{loan.interest}% {loan.interest ? "juros" : "sem juros"}</Text><Text style={styles.heroMuted}>{loan.installments} parcelas · {loan.frequency}</Text></View></Card><View style={styles.actionRow}><Button title="Ativo / Informações" small icon="info-outline" outline color="#34d399" onPress={() => go("loan-info", loan.id)} /><Button title="Editar crédito" small icon="edit" outline color="#a855f7" onPress={() => go("loan-form", loan.id)} /></View><View style={styles.tabs}>{["Plano de pagamento", "Registro", "Gestões"].map((x) => <Pressable key={x} onPress={() => setTab(x)} style={[styles.tab, tab === x && styles.activeTab]}><Text style={[styles.tabText, tab === x && styles.activeTabText]}>{x}</Text></Pressable>)}</View>{tab === "Plano de pagamento" && <><SectionTitle title="Parcelas" action="Registrar pagamento" onPress={() => go("payment", loan.id)} />{Array.from({ length: loan.installments }).map((_, i) => { const amount = loan.installment; const paid = Math.min(amount, Math.max(0, loan.paid - i * amount)); const status = paid >= amount ? "Pago" : i === Math.floor(loan.paid / amount) && loan.status === "Atrasado" ? "Atrasado" : "Pendente"; return <Card key={i} style={styles.installment}><View style={styles.between}><Text style={styles.rowTitle}>Parcela {i + 1}</Text><Badge text={status} color={status === "Pago" ? "#34d399" : status === "Atrasado" ? "#f97316" : "#fbbf24"} /></View><View style={styles.installmentGrid}><Info label="Balança principal" value={money(Math.max(0, loan.capital - paid))} /><Info label="Saldo de juros" value={money(Math.max(0, total - loan.capital - Math.max(0, loan.paid - loan.capital)))} /><Info label="Total pago" value={money(paid)} /><Info label="Balanço total" value={money(Math.max(0, amount - paid))} /></View><Text style={styles.expire}>Expira em {loan.frequency.toLowerCase()} · menu de ações disponível</Text><Button title={status === "Pago" ? "Ver recibo" : "Pagar parcela"} small outline color={status === "Pago" ? "#3b82f6" : "#34d399"} onPress={() => status === "Pago" ? go("receipt", state.payments.find((p) => p.loanId === loan.id)?.id) : go("payment", loan.id)} /></Card>; })}</>}{tab === "Registro" && <Record state={state} loan={loan} go={go} />}{tab === "Gestões" && <Management loan={loan} notify={notify} />}</ScrollView>; }
function Record({ state, loan, go }: { state: AppState; loan: Loan; go: (n: string, id?: string) => void }) { const records = state.payments.filter((p) => p.loanId === loan.id); return <><SectionTitle title="Registro de pagamentos" action="Recibos" onPress={() => go("receipt", records[0]?.id)} />{records.length ? records.map((p) => <Card key={p.id} style={styles.record}><MaterialIcons name="check-circle" size={22} color="#34d399" /><View style={styles.flex}><Text style={styles.rowTitle}>{money(p.amount)} · {p.kind}</Text><Text style={styles.rowMeta}>{p.date} · {p.id}</Text></View><Pressable onPress={() => go("receipt", p.id)}><Text style={styles.link}>Recibo</Text></Pressable></Card>) : <Empty title="Nenhum pagamento registrado" action="Registrar pagamento" onPress={() => go("payment", loan.id)} />}</>; }
function Management({ loan, notify }: { loan: Loan; notify: (s: string) => void }) { return <><SectionTitle title="Gestões do crédito" /><Card><Info label="Capital pendente" value={money(Math.max(0, loan.capital - loan.paid))} /><Info label="Juros pendentes" value={money(Math.max(0, loan.capital * loan.interest / 100 - Math.max(0, loan.paid - loan.capital)))} /><Info label="Mora pendente" value={money(0)} /><Button title="Renovar crédito" icon="autorenew" onPress={() => notify("Fluxo de renovação preparado")} /><Button title="Enviar lembrete" icon="chat" outline color="#3b82f6" onPress={() => notify("Mensagem pronta para WhatsApp")} /></Card></>; }

function LoanInfo({ loan, state, go }: { loan: Loan; state: AppState; go: (n: string, id?: string) => void }) { const total = loan.capital * (1 + loan.interest / 100); const overdue = loan.status === "Atrasado" ? 1 : 0; const fields = [["ID do empréstimo", loan.id], ["Data do empréstimo", loan.start], ["Próxima data de pagamento", loan.due], ["Data de vencimento do empréstimo", loan.due], ["Pagamentos em atraso", String(overdue)], ["Interesse", `${loan.interest}%`], ["Valor dos juros", money(total - loan.capital)], ["Parcelas pagas", `${Math.floor(loan.paid / loan.installment)} de ${loan.installments}`], ["Frequência de Pagamento", loan.frequency], ["Valor do pagamento", money(loan.installment)], ["Montante total do empréstimo", money(loan.capital)], ["Empréstimo + juros", money(total)], ["Total pago", money(loan.paid)]]; return <ScrollView contentContainerStyle={styles.scroll}><Header title="Informações do crédito" go={go} /><Card>{fields.map(([l, v]) => <Info key={l} label={l} value={v} />)}<View style={styles.divider} /><Info label="Dívida de Capital" value={money(Math.max(0, loan.capital - Math.min(loan.paid, loan.capital)))} /><Info label="Juros Pendentes" value={money(Math.max(0, total - loan.capital - Math.max(0, loan.paid - loan.capital)))} /><Info label="Dívida total" value={money(Math.max(0, total - loan.paid))} /></Card><Button title="Voltar ao crédito" onPress={() => go("loan")} /></ScrollView>; }
function PaymentForm({ loan, register, go }: { loan: Loan; register: (a: number, k: string) => void; go: (n: string, id?: string) => void }) { const [amount, setAmount] = useState(String(loan.installment)); const [kind, setKind] = useState("Exato"); return <ScrollView contentContainerStyle={styles.scroll}><Header title="Registrar pagamento" subtitle="Pagamento é separado do recibo" go={go} /><Card style={styles.paymentHero}><Text style={styles.miniLabel}>SALDO DA PARCELA</Text><Text style={styles.heroValue}>{money(loan.installment)}</Text><Text style={styles.heroMuted}>Principal, juros e mora serão atualizados</Text></Card><FormInput label="Valor recebido" value={amount} onChangeText={setAmount} keyboardType="decimal-pad" placeholder="0,00" /><Text style={styles.formLabel}>Tipo de pagamento</Text><View style={styles.choiceRow}>{["Exato", "Parcial", "Adiantamento"].map((x) => <Pressable key={x} onPress={() => setKind(x)} style={[styles.choice, kind === x && styles.choiceSelected]}><Text style={[styles.choiceText, kind === x && styles.choiceTextSelected]}>{x}</Text></Pressable>)}</View><Card><Info label="Balanço principal" value={money(loan.capital)} /><Info label="Saldo de juros" value={money(loan.capital * loan.interest / 100)} /><Info label="Mora / multa" value={money(0)} /></Card><Button title="Confirmar pagamento" icon="check" onPress={() => register(Number(amount.replace(",", ".")), kind)} /><Button title="Cancelar" outline color="#78838e" onPress={() => go("loan")} /></ScrollView>; }
function Receipt({ payment, state, go }: { payment?: Payment; state: AppState; go: (n: string, id?: string) => void }) { const c = state.clients.find((x) => x.id === payment?.clientId); return <ScrollView contentContainerStyle={styles.scroll}><Header title="Recibo" subtitle="Comprovante de pagamento" go={go} right={<IconButton icon="share" onPress={() => Alert.alert("Compartilhar", "Recibo preparado para compartilhamento.")} />} /><Card style={styles.receipt}><View style={styles.receiptBrand}><View style={styles.logo}><Text style={styles.logoText}>R</Text></View><Text style={styles.receiptBusiness}>{state.business.name}</Text></View><Text style={styles.receiptTitle}>RECIBO DE PAGAMENTO</Text><Text style={styles.receiptNumber}>{payment?.receipt || "REC-0000"}</Text><View style={styles.divider} /><Info label="Cliente" value={c?.name || "Cliente"} /><Info label="Documento" value={c?.document || "Não informado"} /><Info label="Data" value={payment?.date || today} /><Info label="Forma" value={payment?.kind || "Exato"} /><Text style={styles.receiptAmount}>{money(payment?.amount || 0)}</Text><Text style={styles.receiptThanks}>Pagamento recebido com sucesso.</Text><View style={styles.signature}><Text style={styles.signatureLine}>____________________________</Text><Text style={styles.muted}>{state.business.signature}</Text></View></Card><Button title="Imprimir / compartilhar" icon="print" outline color="#3b82f6" onPress={() => Alert.alert("Recibo", "Visualização pronta para impressão ou compartilhamento.")} /><Button title="Voltar" onPress={() => go("dashboard")} /></ScrollView>; }

function LoanForm({ state, add, go }: { state: AppState; add: (d: Partial<Loan>) => void; go: (n: string, id?: string) => void }) { const [clientId, setClientId] = useState(state.clients[0]?.id || ""); const [capital, setCapital] = useState("2400"); const [interest, setInterest] = useState("20"); const [installments, setInstallments] = useState("12"); const [frequency, setFrequency] = useState("Semanal"); const [lateFee, setLateFee] = useState("2"); const [grace, setGrace] = useState("2"); const [note, setNote] = useState(""); const total = Number(capital || 0) * (1 + Number(interest || 0) / 100); const installment = total / Math.max(1, Number(installments || 1)); return <ScrollView contentContainerStyle={styles.scroll}><Header title="Novo crédito" subtitle="Simulação e plano de pagamento" go={go} /><Text style={styles.formLabel}>Cliente</Text><View style={styles.choiceRow}>{state.clients.map((c) => <Pressable key={c.id} onPress={() => setClientId(c.id)} style={[styles.choice, clientId === c.id && styles.choiceSelected]}><Text style={[styles.choiceText, clientId === c.id && styles.choiceTextSelected]}>{c.name.split(" ")[0]}</Text></Pressable>)}</View><FormInput label="Capital" value={capital} onChangeText={setCapital} keyboardType="decimal-pad" placeholder="0,00" /><FormInput label="Juros (%)" value={interest} onChangeText={setInterest} keyboardType="decimal-pad" placeholder="0" /><Text style={styles.formLabel}>Tipo de juros</Text><View style={styles.choiceRow}><View style={styles.choiceSelected}><Text style={styles.choiceTextSelected}>Fixo</Text></View><View style={styles.choice}><Text style={styles.choiceText}>Composto</Text></View></View><FormInput label="Cotas / parcelas" value={installments} onChangeText={setInstallments} keyboardType="number-pad" placeholder="12" /><Text style={styles.formLabel}>Frequência</Text><View style={styles.choiceRow}>{["Diária", "Semanal", "Quinzenal", "Mensal"].map((x) => <Pressable key={x} onPress={() => setFrequency(x)} style={[styles.choice, frequency === x && styles.choiceSelected]}><Text style={[styles.choiceText, frequency === x && styles.choiceTextSelected]}>{x}</Text></Pressable>)}</View><FormInput label="Data do empréstimo" value={today} onChangeText={() => {}} placeholder={today} /><FormInput label="Mora / multa (%)" value={lateFee} onChangeText={setLateFee} keyboardType="decimal-pad" placeholder="0" /><FormInput label="Tolerância / grace (dias)" value={grace} onChangeText={setGrace} keyboardType="number-pad" placeholder="0" /><FormInput label="Observações / notes" value={note} onChangeText={setNote} placeholder="Notas do crédito" multiline /><Card style={styles.simulation}><Text style={styles.sectionText}>Simulação</Text><Info label="Empréstimo + juros" value={money(total)} /><Info label="Valor de cada parcela" value={money(installment)} /><Info label="Plano" value={`${installments} parcelas ${frequency.toLowerCase()}`} /></Card><Button title="Criar crédito e plano" icon="check" onPress={() => add({ clientId, capital: Number(capital), interest: Number(interest), installments: Number(installments), installment, frequency, lateFee: Number(lateFee), grace: Number(grace), due: today, start: today, note })} /><Button title="Cancelar" outline color="#78838e" onPress={() => go("loans")} /></ScrollView>; }

function Finance({ state, go, notify }: { state: AppState; go: (n: string, id?: string) => void; notify: (s: string) => void }) { const received = state.payments.reduce((a, p) => a + p.amount, 0); const expenses = state.expenses.reduce((a, e) => a + e.amount, 0); return <ScrollView contentContainerStyle={styles.scroll}><Header title="Caixa / Financeiro" subtitle="Entradas, saídas e fechamento diário" go={go} /><View style={styles.metricGrid}><Metric title="Saldo" value={money(received - expenses)} color="#34d399" /><Metric title="Entradas" value={money(received)} color="#3b82f6" /><Metric title="Saídas" value={money(expenses)} color="#f97316" /><Metric title="Pendente" value={money(state.loans.reduce((a, l) => a + Math.max(0, l.capital * (1 + l.interest / 100) - l.paid), 0))} color="#fbbf24" /></View><SectionTitle title="Movimentações de hoje" /><Card>{state.payments.slice(0, 4).map((p) => <View key={p.id} style={styles.record}><MaterialIcons name="arrow-downward" size={20} color="#34d399" /><View style={styles.flex}><Text style={styles.rowTitle}>Pagamento {p.id}</Text><Text style={styles.rowMeta}>{p.date} · {p.kind}</Text></View><Text style={styles.amount}>{money(p.amount)}</Text></View>)}{state.expenses.map((e) => <View key={e.id} style={styles.record}><MaterialIcons name="arrow-upward" size={20} color="#f97316" /><View style={styles.flex}><Text style={styles.rowTitle}>{e.title}</Text><Text style={styles.rowMeta}>{e.category} · {e.date}</Text></View><Text style={[styles.amount, { color: "#f97316" }]}>-{money(e.amount)}</Text></View>)}</Card><Button title="Adicionar despesa" icon="add" onPress={() => go("expenses")} /><Button title="Fechamento diário" icon="lock" outline color="#a855f7" onPress={() => go("cash-close")} /><Button title="Exportar caixa" icon="file-download" outline color="#3b82f6" onPress={() => notify("Exportação do caixa preparada")} /></ScrollView>; }
function Metric({ title, value, color }: { title: string; value: string; color: string }) { return <Card style={styles.metric}><View style={[styles.dot, { backgroundColor: color }]} /><Text style={styles.metricTitle}>{title}</Text><Text style={styles.metricValue}>{value}</Text></Card>; }
function Expenses({ state, setState, go, notify }: { state: AppState; setState: React.Dispatch<React.SetStateAction<AppState>>; go: (n: string, id?: string) => void; notify: (s: string) => void }) { const [title, setTitle] = useState(""); const [amount, setAmount] = useState(""); return <ScrollView contentContainerStyle={styles.scroll}><Header title="Despesas" subtitle="Saídas vinculadas ao caixa" go={go} /><FormInput label="Descrição" value={title} onChangeText={setTitle} placeholder="Ex.: combustível" /><FormInput label="Valor" value={amount} onChangeText={setAmount} placeholder="0,00" keyboardType="decimal-pad" /><Button title="Registrar despesa" icon="check" onPress={() => { if (!title || !amount) return; setState((s) => ({ ...s, expenses: [{ id: uid("E"), title, amount: Number(amount.replace(",", ".")), date: today, category: "Operacional" }, ...s.expenses] })); notify("Despesa lançada no Caixa"); setTitle(""); setAmount(""); }} /><SectionTitle title="Histórico" />{state.expenses.map((e) => <Card key={e.id} style={styles.record}><MaterialIcons name="receipt-long" size={20} color="#f97316" /><View style={styles.flex}><Text style={styles.rowTitle}>{e.title}</Text><Text style={styles.rowMeta}>{e.category} · {e.date}</Text></View><Text style={styles.amount}>{money(e.amount)}</Text></Card>)}</ScrollView>; }
function CashClose({ state, go, notify }: { state: AppState; go: (n: string, id?: string) => void; notify: (s: string) => void }) { const inValue = state.payments.reduce((a, p) => a + p.amount, 0); const outValue = state.expenses.reduce((a, e) => a + e.amount, 0); return <ScrollView contentContainerStyle={styles.scroll}><Header title="Fechamento diário" subtitle={today} go={go} /><Card style={styles.closeCard}><Text style={styles.miniLabel}>SALDO DO DIA</Text><Text style={styles.heroValue}>{money(inValue - outValue)}</Text><Info label="Total recebido" value={money(inValue)} /><Info label="Total em despesas" value={money(outValue)} /><Info label="Movimentações" value={`${state.payments.length + state.expenses.length}`} /></Card><Button title="Confirmar fechamento" icon="lock" onPress={() => notify("Caixa fechado com sucesso")} /><Button title="Voltar ao financeiro" outline color="#78838e" onPress={() => go("finance")} /></ScrollView>; }

function Routes({ state, setState, go, notify }: { state: AppState; setState: React.Dispatch<React.SetStateAction<AppState>>; go: (n: string, id?: string) => void; notify: (s: string) => void }) { const [name, setName] = useState(""); return <ScrollView contentContainerStyle={styles.scroll}><Header title="Rotas" subtitle="Organize a ordem de cobrança" go={go} /><FormInput label="Nova rota" value={name} onChangeText={setName} placeholder="Ex.: Rota Sul" /><Button title="Criar rota" icon="add-road" onPress={() => { if (name) { setState((s) => ({ ...s, routes: [...s.routes, { id: uid("r"), name, clients: [] }] })); setName(""); notify("Rota criada"); } }} />{state.routes.map((r) => <Card key={r.id}><View style={styles.between}><View><Text style={styles.rowTitle}>{r.name}</Text><Text style={styles.rowMeta}>{r.clients.length} clientes vinculados</Text></View><IconButton icon="more-vert" onPress={() => Alert.alert(r.name, "Editar rota, ordenar cobrança ou remover cliente.")} /></View>{r.clients.map((cid) => { const c = state.clients.find((x) => x.id === cid); return <View key={cid} style={styles.record}><Avatar name={c?.name || "C"} size={30} /><Text style={styles.flex}>{c?.name}</Text><Text style={styles.link}>Ordenar</Text></View>; })}<Button title="Vincular cliente" small outline color="#3b82f6" onPress={() => notify("Seletor de clientes preparado")} /></Card>)}</ScrollView>; }
function Collections({ state, go, register }: { state: AppState; go: (n: string, id?: string) => void; register: (a: number, k: string) => void }) { const [filter, setFilter] = useState("Pendentes"); const loans = filter === "Todas" ? state.loans : filter === "Pagas" ? state.loans.filter((l) => l.status === "Pago") : state.loans.filter((l) => l.status !== "Pago"); return <ScrollView contentContainerStyle={styles.scroll}><Header title="Cobranças" subtitle="Pendentes, pagas e todas" go={go} /><View style={styles.chips}>{["Pendentes", "Pagas", "Todas"].map((x) => <Pressable key={x} onPress={() => setFilter(x)} style={filter === x ? styles.chipSelected : styles.chip}><Text style={filter === x ? styles.chipSelectedText : styles.chipText}>{x}</Text></Pressable>)}</View>{loans.map((l) => { const c = state.clients.find((x) => x.id === l.clientId); return <Card key={l.id} style={styles.collectionRow}><Avatar name={c?.name || "C"} size={42} /><View style={styles.flex}><Text style={styles.rowTitle}>{c?.name}</Text><Text style={styles.rowMeta}>{money(l.installment)} · vence {l.due}</Text></View><Button title="Pagar" small onPress={() => go("payment", l.id)} /><IconButton icon="chat" onPress={() => Alert.alert("WhatsApp", `Mensagem de cobrança para ${c?.name}.`)} /></Card>; })}{!loans.length && <Card><Text style={styles.muted}>Nenhuma cobrança neste filtro</Text></Card>}</ScrollView>; }
function Reports({ state, go, notify }: { state: AppState; go: (n: string, id?: string) => void; notify: (s: string) => void }) { const received = state.payments.reduce((a, p) => a + p.amount, 0); const expenses = state.expenses.reduce((a, e) => a + e.amount, 0); return <ScrollView contentContainerStyle={styles.scroll}><Header title="Relatórios" subtitle="Resumo financeiro e exportação" go={go} /><Pressable style={styles.dateFilter} onPress={() => notify("Filtro por período aberto")}><MaterialIcons name="date-range" size={18} color="#34d399" /><Text style={styles.dateText}>Período: mês corrente</Text><MaterialIcons name="keyboard-arrow-down" size={19} color="#81909b" /></Pressable><View style={styles.metricGrid}><Metric title="Recebido" value={money(received)} color="#34d399" /><Metric title="Pendente" value={money(state.loans.reduce((a, l) => a + Math.max(0, l.capital * (1 + l.interest / 100) - l.paid), 0))} color="#fbbf24" /><Metric title="Vencido" value={money(state.loans.filter((l) => l.status === "Atrasado").reduce((a, l) => a + l.installment, 0))} color="#f97316" /><Metric title="Saldo" value={money(received - expenses)} color="#3b82f6" /></View><SectionTitle title="Tipos de relatório" />{["Resumo financeiro", "Clientes", "Cobranças", "Entradas e saídas"].map((x) => <Pressable key={x} onPress={() => notify(`${x} selecionado`)}><Card style={styles.record}><MaterialIcons name="assessment" size={22} color="#34d399" /><Text style={styles.flex}>{x}</Text><MaterialIcons name="chevron-right" size={22} color="#68727e" /></Card></Pressable>)}<Button title="Exportar CSV / Excel" icon="file-download" onPress={() => notify("Arquivo preparado para exportação")} /></ScrollView>; }
function Portfolio({ state, go }: { state: AppState; go: (n: string, id?: string) => void }) { const received = state.payments.reduce((a, p) => a + p.amount, 0); return <ScrollView contentContainerStyle={styles.scroll}><Header title="Gestão da Carteira" subtitle="Visão consolidada da operação" go={go} /><View style={styles.metricGrid}><Metric title="Clientes" value={String(state.clients.length)} color="#3b82f6" /><Metric title="Empréstimos" value={String(state.loans.length)} color="#a855f7" /><Metric title="Recebido" value={money(received)} color="#34d399" /><Metric title="Vencido" value={String(state.loans.filter((l) => l.status === "Atrasado").length)} color="#f97316" /></View><SectionTitle title="Carteira por cliente" />{state.clients.map((c) => { const ls = state.loans.filter((l) => l.clientId === c.id); return <Pressable key={c.id} onPress={() => go("client", c.id)}><Card style={styles.collectionRow}><Avatar name={c.name} size={42} /><View style={styles.flex}><Text style={styles.rowTitle}>{c.name}</Text><Text style={styles.rowMeta}>{ls.length} créditos · {c.route}</Text></View><Text style={styles.amount}>{money(ls.reduce((a, l) => a + l.paid, 0))}</Text></Card></Pressable>; })}</ScrollView>; }
function Calculator({ go }: { go: (n: string, id?: string) => void }) { const [capital, setCapital] = useState("2400"); const [rate, setRate] = useState("20"); const [parts, setParts] = useState("12"); const [mode, setMode] = useState("Capital inicial"); const amount = Number(capital.replace(",", ".")) || 0; const interest = (Number(rate.replace(",", ".")) || 0) / 100; const installments = Math.max(1, Number(parts) || 1); const result = mode === "Cada parcela" ? { initial: (amount * installments) / (1 + interest), total: amount * installments, installment: amount } : mode === "Juros compostos bancários" ? { initial: amount, total: amount * Math.pow(1 + interest, installments), installment: amount * Math.pow(1 + interest, installments) / installments } : { initial: amount, total: amount * (1 + interest), installment: amount * (1 + interest) / installments }; return <ScrollView contentContainerStyle={styles.scroll}><Header title="Calculadora" subtitle="Simulação de crédito" go={go} /><View style={styles.choiceRow}>{["Capital inicial", "Cada parcela", "Juros compostos bancários"].map((x) => <Pressable key={x} onPress={() => setMode(x)} style={[styles.choice, mode === x && styles.choiceSelected]}><Text style={[styles.choiceText, mode === x && styles.choiceTextSelected]}>{x}</Text></Pressable>)}</View><FormInput label={mode === "Cada parcela" ? "Valor de cada parcela" : "Capital inicial"} value={capital} onChangeText={setCapital} keyboardType="decimal-pad" placeholder="0,00" /><FormInput label="Juros (%)" value={rate} onChangeText={setRate} keyboardType="decimal-pad" placeholder="0" /><FormInput label="Quantidade de parcelas" value={parts} onChangeText={setParts} keyboardType="number-pad" placeholder="12" /><Card style={styles.simulation}><Text style={styles.sectionText}>Resultado da simulação</Text><Info label="Modo" value={mode} /><Info label="Capital inicial" value={money(result.initial)} /><Info label="Montante" value={money(result.total)} /><Info label="Cada parcela" value={money(result.installment)} /><Info label="Notas" value="Simulação sem compromisso" /></Card><Button title="Limpar campos" outline color="#78838e" onPress={() => { setCapital(""); setRate(""); setParts(""); }} /><Button title="Expandir / recolher campos" outline color="#3b82f6" onPress={() => Alert.alert("Campos avançados", "Datas, frequência, mora e notas estão disponíveis no novo crédito.")} /></ScrollView>; }
function Settings({ state, setState, go, notify }: { state: AppState; setState: React.Dispatch<React.SetStateAction<AppState>>; go: (n: string, id?: string) => void; notify: (s: string) => void }) { return <ScrollView contentContainerStyle={styles.scroll}><Header title="Configurações" subtitle="Personalize o Roots Cobrança" go={go} /><Card><Text style={styles.sectionText}>Dados do negócio</Text><FormInput label="Nome do negócio" value={state.business.name} onChangeText={(v) => setState((s) => ({ ...s, business: { ...s.business, name: v } }))} placeholder="Nome" /><FormInput label="Moeda" value={state.business.currency} onChangeText={(v) => setState((s) => ({ ...s, business: { ...s.business, currency: v } }))} placeholder="BRL" /><FormInput label="Assinatura do recibo" value={state.business.signature} onChangeText={(v) => setState((s) => ({ ...s, business: { ...s.business, signature: v } }))} placeholder="Assinatura" /></Card><SettingRow title="Notificações" icon="notifications" right={<Switch value={true} onValueChange={() => notify("Preferência atualizada")} trackColor={{ true: "#0d9488" }} />} /><SettingRow title="Aparência escura" icon="dark-mode" right={<Switch value={state.dark} onValueChange={(v) => setState((s) => ({ ...s, dark: v }))} trackColor={{ true: "#0d9488" }} />} /><SettingRow title="Backup e sincronização" icon="cloud-sync" onPress={() => notify("Sincronização preparada")} /><SettingRow title="Segurança" icon="lock" onPress={() => notify("Configuração de segurança aberta")} /><SettingRow title="Ajuda e suporte" icon="help-outline" onPress={() => notify("Central de ajuda aberta")} /><SettingRow title="Sair" icon="logout" danger onPress={() => Alert.alert("Sair", "Sessão encerrada com segurança.")} /></ScrollView>; }
function SettingRow({ title, icon, right, onPress, danger }: { title: string; icon: keyof typeof MaterialIcons.glyphMap; right?: React.ReactNode; onPress?: () => void; danger?: boolean }) { return <Pressable onPress={onPress} style={styles.settingRow}><MaterialIcons name={icon} size={22} color={danger ? "#f97316" : "#34d399"} /><Text style={[styles.settingText, danger && { color: "#f97316" }]}>{title}</Text>{right || <MaterialIcons name="chevron-right" size={22} color="#68727e" />}</Pressable>; }
function More({ go }: { go: (n: string, id?: string) => void }) { return <ScrollView contentContainerStyle={styles.scroll}><Header title="Mais" subtitle="Acesso rápido aos módulos" go={go} />{[["Cobranças", "collections", "payments"], ["Caixa / Financeiro", "finance", "account-balance"], ["Despesas", "expenses", "receipt-long"], ["Rotas", "routes", "alt-route"], ["Relatórios", "reports", "assessment"], ["Gestão da Carteira", "portfolio", "pie-chart"], ["Calculadora", "calculator", "calculate"], ["Configurações", "settings", "settings"], ["Sobre o Roots", "about", "info-outline"]].map(([title, target, icon]) => <SettingRow key={target} title={title} icon={icon as keyof typeof MaterialIcons.glyphMap} onPress={() => go(target)} />)}</ScrollView>; }
function About({ go }: { go: (n: string, id?: string) => void }) { return <ScrollView contentContainerStyle={styles.scroll}><Header title="Sobre" subtitle="Roots Cobrança" go={go} /><Card style={styles.about}><View style={styles.logoLarge}><Text style={styles.logoText}>R</Text></View><Text style={styles.profileName}>Roots Cobrança</Text><Text style={styles.muted}>Gerenciador de cobranças e empréstimos</Text><Text style={styles.aboutText}>Controle sua carteira, organize rotas, registre pagamentos e mantenha o caixa atualizado em uma experiência simples e profissional.</Text><Text style={styles.muted}>Versão 1.0.0</Text></Card><Button title="Voltar ao início" onPress={() => go("dashboard")} /></ScrollView>; }
function FormInput({ label, value, onChangeText, placeholder, keyboardType, multiline }: { label: string; value: string; onChangeText: (v: string) => void; placeholder?: string; keyboardType?: any; multiline?: boolean }) { return <View style={styles.formGroup}><Text style={styles.formLabel}>{label}</Text><TextInput value={value} onChangeText={onChangeText} placeholder={placeholder} placeholderTextColor="#64707a" keyboardType={keyboardType} multiline={multiline} style={[styles.input, multiline && styles.inputMulti]} /></View>; }
function Empty({ title, action, onPress }: { title: string; action: string; onPress: () => void }) { return <Card style={styles.empty}><MaterialIcons name="inbox" size={30} color="#64707a" /><Text style={styles.muted}>{title}</Text><Button title={action} small outline color="#34d399" onPress={onPress} /></Card>; }
function BottomNav({ active, go }: { active: string; go: (n: string, id?: string) => void }) { const items = [["dashboard", "Painel", "dashboard"], ["clients", "Clientes", "people"], ["settings", "Config", "settings"], ["more", "Mais", "more-horiz"]] as const; return <View style={styles.bottomNav}>{items.map(([target, label, icon]) => <Pressable key={target} onPress={() => go(target)} style={styles.navItem}><MaterialIcons name={icon as any} size={23} color={active === target ? "#34d399" : "#74808a"} /><Text style={[styles.navText, active === target && { color: "#34d399" }]}>{label}</Text></Pressable>)}</View>; }
function QuickActions({ go, close }: { go: (n: string, id?: string) => void; close: () => void }) { return <Modal transparent animationType="slide" visible onRequestClose={close}><View style={styles.modalBackdrop}><View style={styles.sheet}><View style={styles.sheetHandle} /><Text style={styles.sheetTitle}>Ações rápidas</Text><Quick title="Criar cliente" icon="person-add" color="#3b82f6" onPress={() => go("client-form")} /><Quick title="Criar empréstimo" icon="payments" color="#a855f7" onPress={() => go("loan-form")} /><Quick title="Criar despesa" icon="receipt-long" color="#f97316" onPress={() => go("expenses")} /><Button title="Fechar" outline color="#78838e" onPress={close} /></View></View></Modal>; }
function DateModal({ close, notify }: { close: () => void; notify: (s: string) => void }) { return <Modal transparent animationType="fade" visible onRequestClose={close}><View style={styles.modalBackdrop}><View style={styles.sheet}><Text style={styles.sheetTitle}>Período</Text>{["Hoje", "Ontem", "Últimos 7 dias", "Mês corrente", "Personalizar"].map((x) => <Pressable key={x} style={styles.settingRow} onPress={() => { notify(`Filtro: ${x}`); close(); }}><Text style={styles.settingText}>{x}</Text><MaterialIcons name="chevron-right" size={22} color="#68727e" /></Pressable>)}<Button title="Cancelar" outline color="#78838e" onPress={close} /></View></View></Modal>; }
function MoreModal({ close, go }: { close: () => void; go: (n: string, id?: string) => void }) { return <Modal transparent animationType="fade" visible onRequestClose={close}><View style={styles.modalBackdrop}><View style={styles.sheet}><Text style={styles.sheetTitle}>Mais opções</Text><Button title="Desativar" outline color="#fbbf24" onPress={close} /><Button title="Remover" outline color="#f97316" onPress={close} /><Button title="Cancelar" outline color="#78838e" onPress={close} /></View></View></Modal>; }

